var toolbar;
var groupOf = (page) => {
  if (page.classList.contains("page--carton")) return "shipping";
  if (page.classList.contains("sapona")) return "sapona";
  if (page.classList.contains("custom-factory")) return "others";
  return "upc";
};
var partOf = (node2) => Object.keys(PARTS).find((part) => node2.classList.contains(part));
var keyOf = (node2) => `${groupOf(node2.closest(".page"))}:${partOf(node2)}`;
var storageKey = () => {
  const defaults = brandDefaults();
  const sku = (domElements_default.sku.value.toUpperCase() || defaults.sku).trim();
  return `adjust:${defaults.brandField}:${sku}`;
};
var save = () => {
  try {
    if (Object.keys(adjustments).length) localStorage.setItem(storageKey(), JSON.stringify(adjustments));
    else localStorage.removeItem(storageKey());
  } catch (error) {
  }
};
var load = () => {
  try {
    adjustments = JSON.parse(localStorage.getItem(storageKey())) || {};
  } catch (error) {
    adjustments = {};
  }
};
var apply = () => {
  document.querySelectorAll(PART_SELECTOR).forEach((node2) => {
    const scale = adjustments[keyOf(node2)];
    node2.style.zoom = scale ? `${scale}` : "";
    node2.classList.toggle("adjusted", Boolean(scale));
  });
  domElements_default.preview.dataset.adjustments = Object.keys(adjustments).length;
};
var renderToolbar = () => {
  if (!selected) {
    toolbar.hidden = true;
    return;
  }
  const key = keyOf(selected);
  const scale = adjustments[key] || 1;
  const [group, part] = key.split(":");
  const count = Object.keys(adjustments).length;
  toolbar.querySelector(".adjust__name").textContent = `${PARTS[part]} \xB7 ${GROUP_NAMES[group]}`;
  toolbar.querySelector(".adjust__value").textContent = `${Math.round(scale * 100)}%`;
  toolbar.querySelector('[data-action="smaller"]').disabled = scale <= MIN_SCALE + 1e-3;
  toolbar.querySelector('[data-action="larger"]').disabled = scale >= MAX_SCALE2 - 1e-3;
  toolbar.querySelector('[data-action="reset"]').disabled = scale === 1;
  toolbar.querySelector('[data-action="reset-all"]').disabled = count === 0;
  toolbar.querySelector('[data-action="reset-all"] span').textContent = count ? `Reset all (${count})` : "Reset all";
  toolbar.hidden = false;
  position();
};
var position = () => {
  if (!selected || toolbar.hidden) return;
  const rect = selected.getBoundingClientRect();
  const width = toolbar.offsetWidth;
  const left = Math.min(Math.max(8, rect.left + rect.width / 2 - width / 2), window.innerWidth - width - 8);
  const above = rect.top - toolbar.offsetHeight - 8;
  toolbar.style.left = `${left}px`;
  toolbar.style.top = `${above > 8 ? above : rect.bottom + 8}px`;
};
var select = (node2) => {
  selected?.classList.remove("adjust--selected");
  selected = node2;
  selected?.classList.add("adjust--selected");
  renderToolbar();
};
var hideAdjustUI = (hidden) => {
  if (hidden) select(null);
  document.body.classList.toggle("adjust-hidden", hidden);
};
var change = (action) => {
  const key = keyOf(selected);
  const scale = adjustments[key] || 1;
  if (action === "reset-all") {
    adjustments = {};
  } else {
    const next = action === "reset" ? 1 : Math.round((scale + (action === "larger" ? STEP : -STEP)) * 100) / 100;
    const clamped = Math.min(MAX_SCALE2, Math.max(MIN_SCALE, next));
    if (clamped === 1) delete adjustments[key];
    else adjustments[key] = clamped;
  }
  save();
  apply();
  renderToolbar();
};
var reload = () => {
  load();
  apply();
  renderToolbar();
};
var adjustInit = () => {
  toolbar = document.querySelector(".adjust");
  toolbar.addEventListener("mousedown", (event) => event.preventDefault());
  toolbar.addEventListener("click", (event) => {
    const button = event.target.closest("[data-action]");
    if (button && selected) change(button.dataset.action);
  });
  document.addEventListener("click", (event) => {
    if (toolbar.contains(event.target)) return;
    const part = event.target.closest(PART_SELECTOR);
    const ignored = event.target.closest(".grab__button, .shipping-mark__tihi");
    select(part && !ignored ? part : null);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") select(null);
  });
  domElements_default.preview.querySelector(".preview__content").addEventListener("scroll", position);
  window.addEventListener("resize", position);
  domElements_default.sku.addEventListener("input", reload);
  domElements_default.brand.addEventListener("change", reload);
  window.addEventListener("load", reload);
};

// src/js/modules/toolBar.js
var DEBUG = false;
var upcToggles = domElements_default.controls.querySelectorAll('.visibility--upc input[type="checkbox"]');
var shippingToggles = domElements_default.controls.querySelectorAll('.visibility--shipping input[type="checkbox"]');
var upcButton = domElements_default.controls.querySelector(".download__button--upc");
var shippingButton = domElements_default.controls.querySelector(".download__button--shipping");
var controlInit = () => {
  let previewLayout = document.querySelector(".layout__form");
  let previewVisibility = document.querySelector(".visibility__form");
  previewLayout.addEventListener("submit", (event) => event.preventDefault());
  previewVisibility.addEventListener("submit", (event) => event.preventDefault());
  previewLayout.addEventListener("change", pageLayout);
  previewVisibility.addEventListener("change", pageVisibility);
  pageLayout();
  pageVisibility();
  toggleAll("#upc-select-all", ["#polybag", "#master", "#inner"]);
  toggleAll("#shipping-select-all", ["#shipping_mark_front", "#shipping_mark_side"]);
  pdfButtons();
  pageImgDownload();
};
var toggleAll = (buttonId, checkboxes) => {
  const button = document.querySelector(buttonId);
  const updateButtonClass = (allChecked) => {
    if (allChecked) {
      button.classList.remove("select-all--unchecked");
      button.classList.add("select-all--checked");
    } else {
      button.classList.remove("select-all--checked");
      button.classList.add("select-all--unchecked");
    }
  };
  const checkInitialStatus = () => {
    const allChecked = checkboxes.every((id) => document.querySelector(id).checked);
    updateButtonClass(allChecked);
  };
  const toggleCheckboxes = () => {
    const allChecked = checkboxes.every((id) => document.querySelector(id).checked);
    checkboxes.forEach((id) => {
      const checkbox = document.querySelector(id);
      checkbox.checked = !allChecked;
    });
    updateButtonClass(!allChecked);
    document.querySelector(".visibility__form").dispatchEvent(new Event("change"));
  };
  checkInitialStatus();
  button.addEventListener("click", toggleCheckboxes);
};
var applyAnimation = (element, firstRect, wasHidden, isHiding) => {
  const last = element.getBoundingClientRect();
  const deltaX = firstRect.left - last.left;
  const deltaY = firstRect.top - last.top;
  const deltaW = last.width === 0 ? 1 : firstRect.width / last.width;
  const deltaH = last.height === 0 ? 1 : firstRect.height / last.height;
  let animation;
  if (wasHidden) {
    animation = element.animate([{
      transformOrigin: "center",
      transform: "scale(0)"
    }, {
      transformOrigin: "center",
      transform: "scale(1)"
    }], {
      duration: 250,
      easing: "ease-in-out",
      fill: "both"
    });
  } else {
    animation = element.animate([{
      transformOrigin: "top left",
      transform: `translate(${deltaX}px, ${deltaY}px) scale(${deltaW}, ${deltaH})`
    }, {
      transformOrigin: "top left",
      transform: "none"
    }], {
      duration: 250,
      easing: "ease-in-out",
      fill: "both"
    });
  }
};
var pageVisibility = () => {
  const shouldShow = (checkboxId) => document.querySelector(checkboxId).checked;
  const visibilityStates = {
    polybag: shouldShow("#polybag"),
    master: shouldShow("#master"),
    inner: shouldShow("#inner"),
    "shipping-front": shouldShow("#shipping_mark_front"),
    "shipping-side": shouldShow("#shipping_mark_side")
  };
  const toggleVisibility = (element, type) => {
    element.classList.toggle("page--hidden", !visibilityStates[type]);
  };
  const elements2 = document.querySelectorAll(`.preview__content .page`);
  let firstRects = Array.from(elements2).map((element) => {
    return {
      rect: element.getBoundingClientRect(),
      wasHidden: element.classList.contains("page--hidden")
    };
  });
  elements2.forEach((element, index2) => {
    const dataType = element.getAttribute("data-type");
    if (dataType in visibilityStates) {
      toggleVisibility(element, dataType);
    }
  });
  elements2.forEach((element, index2) => {
    applyAnimation(element, firstRects[index2].rect, firstRects[index2].wasHidden, firstRects[index2].isHiding);
    if (index2 === elements2.length - 1) {
      setTimeout(() => {
        document.body.classList.remove("canvas-animating");
      }, 250);
    }
  });
};
var pageLayout = () => {
  let expand = document.querySelector(".preview__layout #expanded");
  let header = document.querySelector(".preview__layout #header-visibility");
  let pagePreview = document.querySelector(".preview__content");
  const firstRect = pagePreview.getBoundingClientRect();
  const wasHidden = pagePreview.classList.contains("preview__content--hidden");
  if (expand && expand.checked) {
    pagePreview.classList.remove("preview__content--condensed");
    pagePreview.classList.add("preview__content--expanded");
  } else {
    pagePreview.classList.remove("preview__content--expanded");
    pagePreview.classList.add("preview__content--condensed");
  }
  if (header && header.checked) {
    pagePreview.classList.remove("preview__content--header-hidden");
    pagePreview.classList.add("preview__content--header-visible");
  } else {
    pagePreview.classList.remove("preview__content--header-visible");
    pagePreview.classList.add("preview__content--header-hidden");
  }
  applyAnimation(pagePreview, firstRect, wasHidden);
  canvasUpdate();
};
var pdfButtons = () => {
  window.onload = () => buttonBuilder();
  document.querySelector("#brand").addEventListener("change", buttonBuilder);
  document.querySelector("#sku").addEventListener("input", buttonBuilder);
  document.querySelector(".layout__form").addEventListener("change", buttonBuilder);
  document.querySelector(".visibility__form").addEventListener("change", buttonBuilder);
  if (!DEBUG) {
    upcButton.addEventListener("click", () => savePDF(".page--a4"));
    shippingButton.addEventListener("click", () => savePDF(".page--carton"));
  } else {
    window.onload = () => generatePDF(".page");
  }
};
var generatePDF = async (elements2) => {
  const pdf = new E("p", "in", "a4", true);
  const pages = Array.from(document.querySelectorAll(`${elements2}:not(.page--hidden):not(.factory--hidden) .print`));
  let pageType;
  for (const page of pages) {
    if (page.closest(".scaler-wrapper")) page.closest(".scaler-wrapper").classList.add("rendering");
    const scale = printScale(page);
    await toPng(page, {
      quality: 1,
      pixelRatio: 4 / scale
    }).then(function(dataUrl) {
      var img = new Image();
      img.src = dataUrl;
      if (!DEBUG) {
        const originalWidth = page.offsetWidth;
        const originalHeight = page.offsetHeight;
        const imgWidth = pixelToInch(originalWidth / scale);
        const imgHeight = pixelToInch(originalHeight / scale);
        const isShippingMark = page.closest(".page--carton") ? true : false;
        if (isShippingMark || imgWidth > 8.3 || imgHeight > 11.7) {
          const imgData = dataUrl;
          const orientation = imgWidth > imgHeight ? "landscape" : "portrait";
          pageType = "shipping";
          const backgroundColor = [255, 255, 255];
          pdf.addPage([imgWidth, imgHeight], orientation);
          pdf.setFillColor.apply(null, [...backgroundColor]);
          pdf.rect(0, 0, pdf.internal.pageSize.width, pdf.internal.pageSize.height, "F");
          pdf.addImage(imgData, "png", 0, 0, imgWidth, imgHeight);
          if (page === pages[pages.length - 1]) {
            pdf.deletePage(1);
          }
        } else {
          const x4 = (8.3 - imgWidth) / 2;
          const y4 = (11.7 - imgHeight) / 2;
          pageType = "packaging";
          const imgData = dataUrl;
          pdf.addImage(imgData, "png", x4, y4, imgWidth, imgHeight);
          if (page !== pages[pages.length - 1]) {
            pdf.addPage();
          }
        }
      } else {
        page.insertAdjacentElement("afterend", img);
      }
      if (page.closest(".scaler-wrapper")) page.closest(".scaler-wrapper").classList.remove("rendering");
    }).catch(function(error) {
      console.error("oops, something went wrong!", error);
    });
  }
  if (!DEBUG) return { pdf, pageType };
};
var printScale = (print) => parseFloat(print.closest(".page")?.dataset.scale) || 1;
var savePDF = async (elements2) => {
  hideAdjustUI(true);
  const { pdf, pageType } = await generatePDF(elements2).finally(() => hideAdjustUI(false));
  pdf.save(namer(pageType, "pdf"));
};
var buttonBuilder = () => {
  upcButton.setAttribute("data-tooltip", namer("packaging", "pdf"));
  upcButton.setAttribute("data-tooltip-location", "bottom");
  shippingButton.setAttribute("data-tooltip", namer("shipping", "pdf"));
  shippingButton.setAttribute("data-tooltip-location", "bottom");
  disableButtonIfAllUnchecked(upcToggles, upcButton);
  disableButtonIfAllUnchecked(shippingToggles, shippingButton);
};
var disableButtonIfAllUnchecked = (toggles, button) => {
  const allUnchecked = Array.from(toggles).every((toggle) => !toggle.checked);
  button.disabled = allUnchecked;
};
var pageImgDownload = () => {
  const pages = document.querySelectorAll(".page");
  pages.forEach((page) => {
    const download = document.createElement("button");
    download.classList.add("grab__button");
    download.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-big-down-dash"><path d="M15 5H9"/><path d="M15 9v3h4l-7 7-7-7h4V9h6z"/></svg>';
    page.appendChild(download);
  });
  document.querySelectorAll(".grab__button").forEach((button) => {
    button.addEventListener("click", () => {
      const defaults = brandDefaults();
      let brand = domElements_default.brand.value;
      const sku = (domElements_default.sku.value.toUpperCase() || defaults.sku).trim();
      const page = button.closest(".page");
      let type = page.getAttribute("data-type");
      let sapona = page.classList.contains("sapona") ? "-sapona" : "";
      switch (brand) {
        case "brenthaven":
          brand = "BH";
          break;
        case "gumdrop":
          brand = "GD";
          break;
        case "vault":
          brand = "VT";
          break;
      }
      switch (type) {
        case "polybag":
          type = "PB";
          break;
        case "master":
          type = "MC";
          break;
        case "inner":
          type = "IC";
          break;
        case "shipping-front":
          type = "Shipping Marks - Front";
          break;
        case "shipping-side":
          type = "Shipping Marks - Side";
          break;
      }
      const print = page.querySelector(".print");
      const filename = `${brand}.${sku}.${type}${sapona}.png`;
      console.log(filename);
      hideAdjustUI(true);
      toPng(print, { quality: 1, pixelRatio: 4 / printScale(print) }).finally(() => hideAdjustUI(false)).then(function(dataUrl) {
        const link = document.createElement("a");
        link.download = filename;
        link.href = dataUrl;
        link.click();
      });
    });
  });
};

// src/js/modules/labelSize.js
var PRESETS = {
  default: { name: "Default", height: 3.8, width: 3.2 },
  legacy: { name: "Legacy", height: 3.5, width: 3.5 },
  "gumdrop-large": { name: "10 x 8.5 cm", height: 3.94, width: 3.35, metric: "10 x 8.5 cm" }
};
var BASE = PRESETS.default;
var MIN_UNIT = 0.5;
var TITLES = { polybag: "Polybag", master: "Master Carton", inner: "Inner Carton" };
var customInches = (input, fallback) => {
  const value = parseFloat(input.value) || fallback;
  return Math.min(parseFloat(input.max), Math.max(parseFloat(input.min), value));
};
var activeSize = () => {
  if (domElements_default.factory.value !== "custom-size") return PRESETS[domElements_default.factory.value] || BASE;
  return {
    name: "Custom",
    height: customInches(domElements_default.labelHeight, BASE.height),
    width: customInches(domElements_default.labelWidth, BASE.width)
  };
};
var inches = (value) => `${+value.toFixed(2)}"`;
var contentSpan = (row) => {
  const rects = [row, ...row.querySelectorAll("*")].filter((node2) => !node2.closest("svg") || node2.matches(".label__qr svg, .label__datamatrix svg, .label__install-svg svg")).flatMap((node2) => Array.from(node2.getClientRects())).filter((rect) => rect.height > 0);
  return { top: Math.min(...rects.map((rect) => rect.top)), bottom: Math.max(...rects.map((rect) => rect.bottom)) };
};
var fits2 = (label) => {
  const box = label.getBoundingClientRect();
  const tolerance = box.width / label.offsetWidth;
  const rows = Array.from(label.children).filter((row) => row.getClientRects().length);
  const spans = rows.map(contentSpan);
  return label.scrollHeight <= label.clientHeight + 1 && !rows.some((row) => escapes(row, box, tolerance)) && !spans.some((span, i5) => i5 > 0 && spans[i5 - 1].bottom > span.top + tolerance);
};
var fitLabel = (label, size) => {
  const widthRatio = size.width / BASE.width;
  const ceiling = Math.min(widthRatio, Math.max(1, Math.min(widthRatio, size.height / BASE.height)));
  const tryUnit = (unit) => {
    label.style.setProperty("--u", `${unit}px`);
    return fits2(label);
  };
  if (tryUnit(ceiling)) return;
  let low = MIN_UNIT;
  let high = ceiling;
  for (let i5 = 0; i5 < 8; i5++) {
    const mid = (low + high) / 2;
    if (tryUnit(mid)) low = mid;
    else high = mid;
  }
  tryUnit(low);
};
var fitLabels = () => {
  const size = activeSize();
  document.querySelectorAll(".page--a4.default .label").forEach((label) => fitLabel(label, size));
};
var labelSizeUpdate = () => {
  const size = activeSize();
  domElements_default.labelSize.classList.toggle("hidden", domElements_default.factory.value !== "custom-size");
  document.querySelectorAll(".page--a4.default").forEach((page) => {
    const label = page.querySelector(".label");
    label.style.setProperty("--label-w", `${size.width}in`);
    label.style.setProperty("--label-h", `${size.height}in`);
    const metric = size.metric ? ` (${size.metric})` : "";
    page.querySelector(".print-size").textContent = `Label size ${inches(size.height)} tall x ${inches(size.width)} wide${metric}`;
    page.dataset.title = `${TITLES[page.dataset.type]} (${size.name})`;
  });
  fitLabels();
  const master = document.querySelector('.page--a4[data-type="master"]:not(.factory--hidden) .label');
  if (master) {
    domElements_default.preview.style.setProperty("--upc-w", `${master.offsetWidth}px`);
    domElements_default.preview.style.setProperty("--upc-h", `${master.offsetHeight}px`);
    fitShippingMarks();
  }
};
var fitQueued2 = false;
var labelSizeInit = () => {
  domElements_default.labelHeight.addEventListener("input", labelSizeUpdate);
  domElements_default.labelWidth.addEventListener("input", labelSizeUpdate);
  const observer = new MutationObserver((mutations) => {
    if (fitQueued2 || !mutations.some((mutation) => !mutation.target.classList?.contains("label"))) return;
    fitQueued2 = true;
    queueMicrotask(() => {
      fitQueued2 = false;
      fitLabels();
    });
  });
  document.querySelectorAll(".page--a4.default .label").forEach((label) => {
    observer.observe(label, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ["src", "style", "class"] });
    label.addEventListener("load", fitLabels, true);
  });
};

