var tihiUpdate = (event) => {
  let tihiFile = event.target.files[0];
  let reader = new FileReader();
  reader.onloadend = function() {
    localStorage.setItem("uploadedImage", reader.result);
    let img = document.createElement("img");
    img.src = reader.result;
    img.addEventListener("click", resetImage);
    if (domElements_default.printTihi.querySelector("img")) {
      domElements_default.printTihi.querySelector("img").remove();
    }
    domElements_default.printTihi.classList.add("tihi-active");
    domElements_default.printTihi.appendChild(img);
  };
  reader.readAsDataURL(tihiFile);
};
var tihiDragDrop = (event) => {
  event.preventDefault();
  event.stopPropagation();
  if (event.dataTransfer.items) {
    const droppedFile = event.dataTransfer.items[0].getAsFile();
    const changeEvent = {
      target: {
        files: [droppedFile]
      }
    };
    tihiUpdate(changeEvent);
  }
  dragCounter = 0;
  document.body.classList.remove("dragging");
};
var tihiOnload = () => {
  let imageData = localStorage.getItem("uploadedImage");
  if (imageData) {
    let img = document.createElement("img");
    img.src = imageData;
    img.addEventListener("click", resetImage);
    if (domElements_default.printTihi.querySelector("img")) {
      domElements_default.printTihi.querySelector("img").remove();
    }
    domElements_default.printTihi.classList.add("tihi-active");
    domElements_default.printTihi.appendChild(img);
  } else {
    let existingImage = domElements_default.printTihi.querySelector("img");
    if (existingImage) {
      existingImage.addEventListener("click", resetImage);
    }
  }
};
var resetImage = () => {
  if (domElements_default.printTihi.querySelector("img")) {
    domElements_default.printTihi.querySelector("img").remove();
  }
  domElements_default.printTihi.classList.remove("tihi-active");
  localStorage.removeItem("uploadedImage");
};
var dragDropHandler = () => {
  document.addEventListener("dragenter", (event) => {
    dragCounter++;
    if (dragCounter === 1) {
      document.body.classList.add("dragging");
      domElements_default.upcLabel.classList.remove("sidebar__title--active");
      domElements_default.upcForm.classList.remove("sidebar__form--active");
      if (!domElements_default.shipForm.classList.contains("sidebar__form--active")) {
        domElements_default.shipLabel.classList.add("sidebar__title--active");
        domElements_default.shipForm.classList.add("sidebar__form--active");
      }
    }
  });
  document.addEventListener("dragleave", (event) => {
    dragCounter--;
    if (dragCounter === 0) {
      document.body.classList.remove("dragging");
    }
  });
  document.addEventListener("drop", (event) => {
    event.preventDefault();
    dragCounter = 0;
  });
  document.addEventListener("dragover", (event) => {
    event.preventDefault();
  });
};

